Lemma f5cells_bytes : cells_bytes f5cells = repeat (Z_to_bv 8 0xf5) 256.
Proof. vm_compute. repeat (first [reflexivity | apply f_equal2; [apply bv_eq; vm_compute; reflexivity|] ]). Qed.

